-- Up Migration
-- Pinduoduo filing facts per (app_id, user_id, pid). Task B1-06zh (FU-PDD-BINDING-PID, first
-- order); 08 BR-ID-22 ("拼多多：授权状态按 (user_id, pid) 记录"); orchestrator rulings D10-1063 and
-- D10-1097 (B) (couli-runs/FU-PDD-BINDING-PID/plan.md).
--
--   app.union_pdd_pid_filings: one row = "pdd.ddk.member.authority.query answered filed for this
--   user on this pid at filed_at, asked through union_account_id". filed_at is supplied by the
--   caller's Clock (no SQL clock); id is generated by the application (no SQL default).
--
-- Relation to app.union_bindings: that table is untouched here (no column, CHECK or index change);
-- it keeps the per-(app_id, user_id, platform) binding state. A filing row never overrides the
-- binding state: open checks the binding first (blocked / released / missing are refused as before)
-- and only then looks at the filing of the scene pid. Reading and writing this table from linking
-- (the "(user, pid) 粒度" TODO in pdd-authority.ts) is the second order of FU-PDD-BINDING-PID.
--
-- A filing is a fact, so the table is insert-only (db/AGENTS.md rule 4): couli_app gets SELECT and
-- INSERT (insert-if-absent: ON CONFLICT (app_id, user_id, pid) DO NOTHING), couli_readonly SELECT,
-- no role UPDATE / DELETE / TRUNCATE. Re-filing after a lost filing is not modelled: the platform
-- offers no way to learn that a filing was revoked on its side, so a revocation is not visible here;
-- a later authority.query answering "not filed" is handled by linking (30111) without touching the
-- row. Detecting invalidation is left to BR-ID-21 after the S0 verification.
--
-- User-data paths (couli-runs/B1-06zh/user-data-paths.md):
--   - account deletion: rows are kept under the tombstoned user_id (users rows are never deleted);
--     no deletion-cleanup port. The filing key is pid + custom_parameters with the user's attr_code,
--     which no other account reuses; usability is gated by the binding, already blocked on deletion.
--     Retention is "待补登 BR-ID-30, no automatic deletion" like personal_data_copies.
--   - personal-data copy (BR-ID-40): not included, like union_bindings.
--   - account merge (BR-ID-06): not moved to the target account (the filing was made with the source
--     attr_code, the target's links use its own); rows stay under the tombstoned source user.
--
-- Keys: UNIQUE (app_id, user_id, pid) over the whole table (it also serves the user foreign key);
-- FK (app_id, user_id) → users (app_id, id); FK (app_id, platform, union_account_id) →
-- union_accounts (app_id, platform, id) with platform fixed to 'pdd' by CHECK, so the account must
-- be a Pinduoduo account of the same app. No cascading (db/AGENTS.md rule 7).
--
-- Compatibility: additive (one new table, nothing existing changes).
-- Recovery: no down migration. Rollback is DROP TABLE app.union_pdd_pid_filings, only while no
-- row has been written; union_* is an attribution table, so the migration gate refuses that DROP and
-- it needs a gate change approved by the owner (db/AGENTS.md rule 11). Once rows exist they are
-- attribution evidence and are kept; the application simply stops reading and writing them.
--
-- Timeouts: CREATE TABLE with two foreign keys takes SHARE ROW EXCLUSIVE on app.users and
-- app.union_accounts for the short catalog change; the new table is empty, so nothing is scanned.
-- 5s lock wait so a blocked deploy fails fast instead of queueing writers; 30s overall as a ceiling.
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE app.union_pdd_pid_filings (
  id uuid NOT NULL,
  app_id text NOT NULL,
  user_id uuid NOT NULL,
  pid text NOT NULL,
  union_account_id uuid NOT NULL,
  platform text NOT NULL DEFAULT 'pdd',
  filed_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT union_pdd_pid_filings_pkey PRIMARY KEY (id),
  CONSTRAINT union_pdd_pid_filings_user_pid_key UNIQUE (app_id, user_id, pid),
  CONSTRAINT union_pdd_pid_filings_pid_check CHECK (pid <> ''),
  CONSTRAINT union_pdd_pid_filings_platform_check CHECK (platform = 'pdd'),
  CONSTRAINT union_pdd_pid_filings_user_fkey FOREIGN KEY (app_id, user_id)
    REFERENCES app.users (app_id, id),
  CONSTRAINT union_pdd_pid_filings_account_fkey FOREIGN KEY (app_id, platform, union_account_id)
    REFERENCES app.union_accounts (app_id, platform, id)
);

GRANT SELECT, INSERT ON app.union_pdd_pid_filings TO couli_app;
GRANT SELECT ON app.union_pdd_pid_filings TO couli_readonly;
